/**
 * Demo launches, for testing the interface before anything is deployed.
 *
 * These are **not** market data. They are generated by running real buys
 * through the same curve maths the contract uses, so every figure on screen is
 * internally consistent and the curve chart is a true projection of the
 * config — but the launches themselves are invented, and the UI says so
 * unmistakably wherever they appear.
 *
 * Sealed's rule is that chart data is real or absent, never synthesised. The
 * distinction that keeps this on the right side of it: nothing here imitates a
 * live market or a real price. It exercises the interface with arithmetic.
 */

import { EMPTY_PROFILE } from './tokenProfile.ts';
import { NO_RULES } from './launchRules.ts';
import { quoteBuy, type CurveConfig, type CurveState } from './curve.ts';
import type { Launch, LaunchDetail, Trade } from './chain.ts';

/**
 * The demo's block height, shared by the trades and by `currentHeight`.
 *
 * One constant, because two clocks is what produced a ticker reporting every trade
 * as three years old: the trades sat near a fixed height while the height came from
 * the live chain at tens of millions.
 */
export const DEMO_HEIGHT = 12_000_000;

const ONE = 1_000_000_000_000_000_000n;
const amt = (n: bigint) => n * ONE;

export function isDemoMode(): boolean {
  return process.env.NEXT_PUBLIC_DEMO === '1';
}

const BASE_CONFIG: CurveConfig = {
  virtualInj: amt(30n),
  virtualTokens: amt(1_073_000_000n),
  curveSupply: amt(800_000_000n),
  graduationTarget: amt(85n),
  feeBps: 100n,
};

interface Seed {
  id: number;
  symbol: string;
  /** INJ put through the curve, in whole INJ. */
  volume: bigint;
  creator: string;
}

const SEEDS: Seed[] = [
  { id: 1, symbol: 'KAIJU', volume: 3n, creator: 'inj1demo0creator0kaiju000000000000000000x' },
  { id: 2, symbol: 'SOLARIS', volume: 31n, creator: 'inj1demo0creator0solaris00000000000000x' },
  { id: 3, symbol: 'MERIDIAN', volume: 68n, creator: 'inj1demo0creator0meridian0000000000000x' },
  { id: 4, symbol: 'NOCTIS', volume: 140n, creator: 'inj1demo0creator0noctis000000000000000x' },
];

/** Walk the curve with real buys so the state is reachable, not invented. */
function stateAfter(volume: bigint): CurveState {
  const st: CurveState = { injCollected: 0n, tokensSold: 0n, graduated: false };
  let left = amt(volume);
  const step = amt(5n);

  while (left > 0n && !st.graduated) {
    const spend = left < step ? left : step;
    try {
      const q = quoteBuy(BASE_CONFIG, st, spend);
      st.injCollected += q.injInAfterFee;
      st.tokensSold += q.tokensOut;
      if (q.graduates) st.graduated = true;
      left -= spend - q.refund;
      if (q.refund >= spend) break;
    } catch {
      break;
    }
  }
  return st;
}

function denomFor(symbol: string): string {
  return `factory/inj1demo000000000000000000000000000000/${symbol}`;
}

export function demoLaunches(): Launch[] {
  return SEEDS.map((s) => ({
    id: s.id,
    denom: denomFor(s.symbol),
    creator: s.creator,
    curve: `inj1demo0curve${String(s.id).padStart(2, '0')}0000000000000000000000x`,
    /*
     * No links on a demo launch, and no placeholder image either. A fabricated logo
     * would make the demo look more finished than the product is, and the demo banner
     * already says these are not real launches: inventing artwork for them would be the
     * same category of thing as a seed price rendered as a live feed.
     */
    profile: EMPTY_PROFILE,
  }));
}

export function demoDetail(id: number): LaunchDetail | null {
  const seed = SEEDS.find((s) => s.id === id);
  if (!seed) return null;
  const state = stateAfter(seed.volume);
  return {
    denom: denomFor(seed.symbol),
    quoteDenom: 'inj',
    creator: seed.creator,
    lpReserve: amt(200_000_000n),
    /*
     * KAIJU carries a cap so the rules panel is exercised in the demo; the rest are
     * open. A demo where every launch looks identical hides the half of the UI that
     * only appears when a rule exists, which is how an unstyled or unwired panel
     * ships: nobody ever sees it locally.
     */
    rules:
      seed.symbol === 'KAIJU'
        ? { maxPerWallet: amt(5_000_000n), tradeStart: null, earlyFee: null, openedAt: null }
        : seed.symbol === 'SOLARIS'
          ? /*
             * Opens in an hour from whenever the page is rendered, so the "not open
             * yet" panel is visible in the demo instead of only existing in a test.
             * Relative rather than a fixed date: a hardcoded timestamp quietly passes
             * and the state stops being reachable, which is how a branch nobody can
             * see gets broken without anyone noticing.
             */
            { maxPerWallet: null, tradeStart: Math.floor(Date.now() / 1000) + 3600, earlyFee: null, openedAt: null }
          : seed.symbol === 'MERIDIAN'
            ? /*
               * An opening fee still running, so the decaying-fee state is visible in
               * the demo rather than only in a test. `openedAt` is five minutes ago of
               * a ten-minute window, so it renders mid-decay instead of at either end
               * where the interesting half would be invisible.
               */
              {
                maxPerWallet: null,
                tradeStart: null,
                earlyFee: { startBps: 1_000, seconds: 600 },
                openedAt: Math.floor(Date.now() / 1000) - 300,
              }
            : NO_RULES,
    config: BASE_CONFIG,
    state,
    migrated: state.graduated,
    platformOwed: 0n,
    creatorOwed: 0n,
  };
}

export function demoDetailByCurve(curveAddress: string): LaunchDetail | null {
  const launch = demoLaunches().find((l) => l.curve === curveAddress);
  return launch ? demoDetail(launch.id) : null;
}

/**
 * Trades for a demo curve, so the ticker and the fills chart are visible locally.
 *
 * Without these the demo renders a board with no activity at all, which means the
 * ticker never appears on any machine until a real launch exists. That is how a
 * component ships unstyled or broken: nobody has looked at it, because nothing could
 * make it render. The rules panel and the "not open yet" state needed the same
 * treatment for the same reason.
 *
 * Derived from the curve address so a given launch always shows the same trades, and
 * so two launches do not show identical feeds. Every figure stays inside the curve's
 * own scale: a demo that renders implausible numbers trains the eye to ignore them.
 */
export function demoTrades(curveAddress: string, limit: number): Trade[] {
  const detail = demoDetailByCurve(curveAddress);
  if (!detail) return [];

  // A stable per-curve seed, so the same launch shows the same history on every
  // render rather than reshuffling on each page load.
  let seed = 0;
  for (const ch of curveAddress) seed = (seed * 31 + ch.charCodeAt(0)) >>> 0;
  const next = () => {
    seed = (seed * 1_103_515_245 + 12_345) >>> 0;
    return seed / 0xffffffff;
  };

  const out: Trade[] = [];
  /*
   * Staggered per curve, so the four demo launches do not all show a trade in the
   * same block and read as "0s" four times over. Not impossible on a real chain,
   * just not what a feed looks like, and the demo exists to show what one looks like.
   */
  const base = DEMO_HEIGHT - Math.floor(next() * 30);
  for (let i = 0; i < limit; i += 1) {
    const r = next();
    const buy = r > 0.35;
    const quote = BigInt(Math.max(1, Math.round(r * 4 * 1e18)));
    out.push({
      kind: buy ? 'buy' : 'sell',
      who: `inj1demo${Math.floor(next() * 1e6)}trader00000000000000000x`,
      injIn: buy ? quote : null,
      injOut: buy ? null : quote,
      tokens: BigInt(Math.round(next() * 5_000_000 * 1e18)),
      fee: quote / 100n,
      height: base - i * (2 + Math.floor(next() * 40)),
      txHash: `DEMO${curveAddress.slice(-6).toUpperCase()}${String(i).padStart(3, '0')}`,
    });
  }
  return out;
}
